<?php $item = fin_demo_product(); get_header(); ?><div class="container section-top"><?php fin_breadcrumb('Products / ' . $item['vi']); ?><article class="demo-product-layout"><div class="demo-gallery"><img src="<?php echo esc_url(fin_image($item['id'])); ?>" alt="<?php echo esc_attr($item['vi']); ?>" width="800" height="800"><span class="image-caption">FINNORA OBJECTS / <?php echo esc_html($item['en']); ?></span></div><div class="demo-product-copy"><h1><?php echo esc_html($item['vi']); ?></h1><p class="product-english"><?php echo esc_html($item['en']); ?></p><p class="large-price"><?php echo esc_html('$' . number_format_i18n($item['price'], 2)); ?> <small>USD · demo price</small></p><p><?php echo esc_html($item['descVi']); ?></p><div class="demo-option"><span>AVAILABLE SIZES</span><div class="size-options"><?php foreach ($item['sizes'] as $size) : ?><span><?php echo esc_html($size); ?></span><?php endforeach; ?></div></div><div class="demo-option"><span>COLOUR</span><p><?php echo esc_html(implode(' · ', $item['colorsVi'])); ?></p></div><div class="info-note">This is a display sample, not available to order. Images do not confirm the final material, fit or printed colour.</div><a class="button full-width" href="<?php echo esc_url(fin_page_url('contact')); ?>">Ask about this design ↗</a><?php if (fin_demo_experience_mode($item) === 'try') fin_try_on($item['vi'], fin_try_asset($item['id'])); ?><div class="product-faq"><details open><summary>About this piece</summary><p><?php echo esc_html($item['descVi']); ?> Check a physical sample before production.</p></details><details><summary>What is print on demand?</summary><p>Artwork is printed onto a product after an order is placed. This demo is not connected to a production partner.</p></details></div></div></article><?php $mode = fin_demo_experience_mode($item); if ($mode !== 'try') { $items = [$item]; foreach (fin_catalog() as $entry) if ($entry['id'] !== $item['id'] && fin_demo_experience_mode($entry) === $mode) $items[] = $entry; fin_showroom(array_map('fin_experience_demo_item', $items), $mode); } ?><section class="section"><div class="section-heading"><h2>You might <em>also like.</em></h2><a class="text-link" href="<?php echo esc_url(fin_shop_url()); ?>">Explore the collection ↗</a></div><div class="product-grid"><?php $n = 0; foreach (fin_catalog() as $related) { if ($related['id'] === $item['id']) continue; fin_product_card($related); if (++$n === 4) break; } ?></div></section></div><?php get_footer(); ?>
